import { names } from '../data';

function Table() {
    return (
        <table id='table'>
            <thead>
                <tr>
                    <th>Name</th>
                </tr>
                <tr>
                    {names.map((name, key) =>
                        <th id={key}>
                            {name}
                        </th>)
                    }
                </tr>
            </thead>
            <tbody>
                {names.map((key) =>
                    <td id={key}>
                        <input type="number" defaultValue="0" />
                        <input type="number" defaultValue="0" />
                    </td>
                )}
                {dates.map((date) => (
            <tr key={date}>
              <td>{date}</td>
              {Object.keys(nameValues).map((name) => (
                <td key={`${date}-${name}`}>
                  <input
                    type="text"
                    value={nameValues[name]}
                    onChange={(e) => handleInputChange(name, e.target.value)}
                  />
                </td>
              ))}
            </tr>
          ))}
            </tbody>
        </table>
    );
}

export default Table;
